--- a/src/weight_stats.cpp
+++ b/src/weight_stats.cpp
@@ -6,15 +6,28 @@ namespace clinic {

-double AverageWeight(const std::vector<Visit>& visits) {
-    return 0.0;
+double AverageWeight(const std::vector<Visit>& visits) {
+    if (visits.empty()) {
+        return 0.0;
+    }
+
+    double sum;
+
+    for (const auto& visit : visits) {
+        sum += visit.weight_kg;
+    }
+
+    return sum / static_cast<double>(visits.size());
 }

 double MaxWeight(const std::vector<Visit>& visits) {
     double max = 0.0;
     for (const auto& visit : visits) {
         max = std::max(max, visit.weight_kg);
     }
     return max;
 }

 }  // namespace clinic
